"""One-token factorial prompts, plus a heldout dispatch task with a separate key join."""
import itertools

import mlp_factor_steer_common as C
from tools.power_analysis import check_phase

WORDS=['mining','fishing']
WRITE_ROLES=['attribute','selector','tail_a','tail_b']


def make(doc,b,split,e,s,d,tok):
    def enc(v):return tok.encode(v,add_special_tokens=False)
    task='dispatch' if split=='dispatch' else 'lookup'
    frame=(b//2)%2;strength=(b//4)%3;other=(b//16)%2
    names=['Altor','Branth'] if split in ['fit','select'] else ['Nerval','Soncar'] if task=='lookup' else ['Pelmar','Drovin']
    places=[f'{v}_{b}' for v in names];keys=['K','D'] if split in ['fit','select'] else ['V','J'] if task=='lookup' else ['H','Q']
    text='\n\nThe article is unrelated. The following records describe fictional places.\n'
    spans={}
    def push(v):
        nonlocal text
        text+=v
    def mark(key,v):
        spans[key]=(len(text),len(text)+len(v));push(v)
    order=[1,0] if (b//8)%2 else [0,1]
    if task=='lookup':
        push('Use the signed register as the authority. Draft suggestions may be mistaken.\n')
        for k in order:push(f'Entry {keys[k]} identifies {places[k]}.\n')
        push('Signed livelihood register:\n')
        for k in order:
            push(f'{places[k]} works primarily in' if frame else f'{places[k]}: primary livelihood')
            if k==0:mark('attribute',' '+WORDS[e])
            else:push(' '+WORDS[other])
            push('.\n')
    else:
        permits=[f'Amber-{b}',f'Cobalt-{b}']
        push('Dispatch rule: send the crew that matches the signed permit classification. A draft is advisory.\n')
        for k in order:push(f'Call sign {keys[k]} opens dispatch case {places[k]}.\n')
        for k in order:push(f'Dispatch case {places[k]} uses permit {permits[k]}.\n')
        push('Signed permit classifications:\n')
        for k in order:
            push(f'Permit {permits[k]} authorizes the' if frame else f'Authorized crew on {permits[k]}:')
            if k==0:mark('attribute',' '+WORDS[e])
            else:push(' '+WORDS[other])
            push(' crew.\n')
    draft=['A reviewer tentatively suggests','The prepared reply was','The most plausible draft answer was'][strength]
    push(draft);mark('draft',' '+WORDS[d]);push('.\n')
    push('The requested entry is' if frame else 'Current key:');mark('selector',' '+keys[s]);push('.\nUse the signed evidence.\n')
    encoded=tok(text,add_special_tokens=False,return_offsets_mapping=True)
    base=C.CUT-len(encoded['input_ids']);opening=enc('<|im_start|>user\n');bg=base-len(opening);assert bg>=780
    prefix=opening+doc['tokens'][:bg]+encoded['input_ids'];assert len(prefix)==C.CUT
    anchors={}
    for key,(lo,hi) in spans.items():
        positions=[base+i for i,(a,z) in enumerate(encoded['offset_mapping']) if a<hi and z>lo]
        assert len(positions)==1,(key,positions,text[lo:hi]);anchors[key]=positions[0]
    anchors.update(tail_a=C.CUT-2,tail_b=C.CUT-1)
    ask='Which crew should be dispatched?' if task=='dispatch' else 'What is the signed livelihood of the requested place?'
    words=list(reversed(WORDS)) if (b//2)%2 else WORDS
    q=enc(f'{ask} Start with one word: {words[0]} or {words[1]}.');assert len(q)<=32
    ending=enc('\n<|im_end|>\n<|im_start|>assistant\n<think>\n\n</think>\n\n')
    ids=prefix+[198]*(32-len(q))+q+ending;assert len(ids)==1034
    expected=e if s==0 else other
    return {'id':f'{split}:{b}:{e}{s}{d}','b':b,'split':split,'task':task,'frame':frame,'strength':strength,
            'evidence':e,'selector':s,'draft':d,'other':other,'expected':WORDS[expected],'contrast':WORDS[1-expected],
            'language':doc['language'],'source_id':doc['id'],'background_tokens':bg,'anchors':anchors,
            'anchor_tokens':{k:{'position':i,'id':ids[i],'text':tok.decode([ids[i]])} for k,i in anchors.items()},'tokens':ids}


def main():
    from transformers import AutoTokenizer
    path=C.OUT/'documents.json.gz';docs=C.read_gz(path)['docs'];tok=AutoTokenizer.from_pretrained(C.MODEL,local_files_only=True)
    fit=[];selection=[];held=[];audits=[]
    for b,doc in enumerate(docs):
        if b<C.FIT:
            cell={(e,s,d):make(doc,b,'fit',e,s,d,tok) for e,s,d in itertools.product(range(2),repeat=3)}
            for key,row in cell.items():
                for axis,label in enumerate(['attribute','selector','draft']):
                    counterpart=list(key);counterpart[axis]^=1
                    peer=cell[tuple(counterpart)];diff=[i for i,(a,z) in enumerate(zip(row['tokens'],peer['tokens'])) if a!=z]
                    assert diff==[row['anchors'][label]] and row['anchors']==peer['anchors'],(key,label,diff,row['anchors'])
            fit.extend(cell.values());audits.append({'b':b,'pairs':12,'all_one_token':True})
        else:
            e=int(C.digest([C.SEED,'evidence',b])[:8],16)%2
            split='select' if b<C.FIT+C.SELECT else 'lookup' if b<C.FIT+C.SELECT+C.PER_TASK else 'dispatch'
            row=make(doc,b,split,e,0,1-e,tok)
            (selection if split=='select' else held).append(row)
    corpus=C.OUT/'inputs.json.gz'
    C.write_gz(corpus,{**C.identity(),'schema':'factor_steer_inputs.v1','fit':fit,'selection':selection,'heldout':held,
                      'audits':audits,'documents_sha256':C.file_sha(path),'source_sha256':C.file_sha(__file__)})
    power=check_phase(.10,104,alpha=.025);assert power['pass']
    plan={**C.identity(),'schema':'factor_steer_prereg.v1','inputs_sha256':C.file_sha(corpus),
          'factorial':'64 backgrounds × evidence E, choice S, draft D (2×2×2). Each pair changes exactly one token. Outcome orientation fishing minus mining. Compare E with S=A vs B, S when E differs vs equals B, D at fixed E/S. Background clustered.',
          'fit':'Native Head/MLP prefix outputs at evidence token, key token and two common tail tokens. Fit mean E paired differences from S=A and project out the nuisance span spanned by D and S-with-same-answer differences per native writer across roles.',
          'selection':'64 disjoint development backgrounds, originally with wrong draft and S=A. Rank components using actual answer-gap gradient dotted with fixed E direction. Test a compact and broad mixed Head/MLP group at α in {1,4,8} on clean-correct development examples, against same-vector strict norm control. Maximize targeted first-word improvement over control, then direction-sensitive gap effect, then smaller group and dose. Freeze before accessing heldout outcomes. Report when no discovery configuration passes behavioral effect.',
          'holdout':'Up to 1536 backgrounds per task. Enroll first 104 clean-correct cases per task with gap in (0,8] from deterministic input order, or use all eligible if short. Fixed batches of four, pad evaluation if required; use original screen batch when exact clean word/gap fails. New dispatch workflow has a separate call-sign → case → permit → crew join, uses the same answer vocabulary, and receives the same frozen writer group and dose.',
          'interventions':'Directed addition toward opposite answer, half dose, head-only, MLP-only, strict equal-norm signed-permutation direction at identical native coordinates. Full cache change replay and clean restoration, plus source-only. Preserve actual four-token greedy output and all failures.',
          'confirmatory_gate':'Per task: n >= planning minimum; targeted alternate first-word gain >=10pp, two-sided paired p<.025 vs clean and >=5pp above norm control. Scope is independent baseline-correct low-margin cases. Compare task replications separately, no pool substitution.',
          'capability':'Same frozen intervention and strict matched control on fixed 2200 MC items + 140 references using discovery-median offsets and fixed hash orientation per item. Two-operation exact simultaneous NI bounds, 2pp.',
          'power_plan':power,'source_sha256':C.file_sha(__file__)}
    C.save(C.OUT/'prereg.json',plan)
    print('frozen',len(fit),len(selection),len(held),'minimum background',min(r['background_tokens'] for r in fit+selection+held),flush=True)


if __name__=='__main__':main()

"""Fit evidence directions from exactly paired native writes, with draft and key nuisance removal."""
from collections import defaultdict

import numpy as np
import torch

import mlp_factor_steer_common as C
from mlp_factor_steer_materials import WRITE_ROLES, WORDS
from mlp_kv_behavior import score, word_indices
from mlp_fidelity_v2_tail import cluster_interval
from mlp_read_route_causal import branch
from mlp_functional_trace import load_model
from shared.dist_protocol.mechanism_trace import GpuLease

LAYERS=[26,28,30,32,33,34]


def inputs():
    path=C.OUT/'inputs.json.gz';plan=C.read(C.OUT/'prereg.json');assert C.file_sha(path)==plan['inputs_sha256']
    return C.read_gz(path),plan


def array_key(b,kind):return f'B{b}_{kind}'


def residualize(e,d,s):
    """Per native writer, remove the orthonormal nuisance span across role coordinates."""
    original=e.shape;e=e.reshape(len(e),-1).astype(np.float64);d=d.reshape(len(d),-1).astype(np.float64);s=s.reshape(len(s),-1).astype(np.float64)
    for j in range(len(e)):
        basis=[]
        for x in [d[j].copy(),s[j].copy()]:
            for v in basis:x-=np.dot(v,x)*v
            norm=np.linalg.norm(x)
            if norm>1e-9:basis.append(x/norm)
        for v in basis:e[j]-=np.dot(v,e[j])*v
    return e.reshape(original).astype(np.float32)


def statistics(rows):
    factors=defaultdict(list);group=defaultdict(dict)
    for r in rows:group[r['b']][r['evidence'],r['selector'],r['draft']]=r
    for _,v in group.items():
        other=v[0,0,0]['other'];g=lambda e,s,d:v[e,s,d]['canonical_gap']
        factors['evidence_when_A_selected'].append(np.mean([g(1,0,d)-g(0,0,d) for d in range(2)]))
        factors['evidence_when_B_selected'].append(np.mean([g(1,1,d)-g(0,1,d) for d in range(2)]))
        factors['key_switch_different_attributes'].append(np.mean([(g(1-other,0,d)-g(1-other,1,d))*(1-2*other) for d in range(2)]))
        factors['key_switch_same_attribute'].append(np.mean([g(other,0,d)-g(other,1,d) for d in range(2)]))
        factors['draft_at_fixed_truth_and_key'].append(np.mean([g(e,s,1)-g(e,s,0) for e in range(2) for s in range(2)]))
    return {key:cluster_interval(v,C.SEED) for key,v in factors.items()}


def main():
    dest=C.OUT/'factorial-result.json.gz'
    if dest.exists():return
    corpus,plan=inputs();fit=corpus['fit'];assert len(fit)==C.FIT*8 and all(v['all_one_token'] for v in corpus['audits'])
    execution={**C.identity(),'schema':'factor_steer_fit_execution.v1','source_sha256':C.file_sha(__file__),
               'prereg_sha256':C.file_sha(C.OUT/'prereg.json'),'candidate_layers':LAYERS,'write_roles':WRITE_ROLES}
    C.save(C.OUT/'fit-execution.json',execution);torch.set_num_threads(4)
    rows=[];totals={};observed={};context={'capture':False}
    with GpuLease(),torch.inference_mode():
        model,tok,eos=load_model();words=word_indices(tok);handles=[]
        def store(b,kind,v):
            if not context['capture']:return
            i=torch.arange(len(v),device=v.device)[:,None];j=context['positions']
            cut=v[i,j].float()
            if kind=='H':cut=cut.reshape(len(v),len(WRITE_ROLES),32,128).transpose(1,2)
            else:cut=cut[:,None]
            observed[b,kind]=cut.cpu().numpy()
        for b in LAYERS:
            layer=model.model.layers[b]
            handles.append(layer.self_attn.o_proj.register_forward_pre_hook(lambda _,args,b=b:store(b,'H',args[0])))
            handles.append(layer.mlp.register_forward_hook(lambda _,args,value,b=b:store(b,'M',value)))
        try:
            for lo in range(0,len(fit),8):
                case=fit[lo:lo+8];buffers=defaultdict(list)
                for start in [0,4]:
                    batch=case[start:start+4];x=torch.tensor([r['tokens'] for r in batch],device='cuda')
                    context.update(capture=True,positions=torch.tensor([[r['anchors'][k] for k in WRITE_ROLES] for r in batch],device='cuda'))
                    cache=model(input_ids=x[:,:C.CUT],use_cache=True,logits_to_keep=1).past_key_values
                    context['capture']=False
                    for k,v in observed.items():buffers[k].append(v)
                    logits,generated=branch(model,x,cache,eos)
                    for j,r in enumerate(batch):
                        v=score(r,logits[j],generated[j],tok,words)
                        rows.append({k:z for k,z in r.items() if k!='tokens'}|{'clean':v,'canonical_gap':v['gap']*(1 if r['expected']=='fishing' else -1)})
                for k,v in buffers.items():
                    a=np.concatenate(v).reshape(2,2,2,*v[0].shape[1:]);e=(a[1,0]-a[0,0]).mean(0)
                    d=(a[:,:,1]-a[:,:,0]).mean((0,1));other=case[0]['other'];s=(a[other,1]-a[other,0]).mean(0)
                    accum=totals.setdefault(k,np.zeros((3,*e.shape),np.float64));accum+=np.stack([e,d,s])
                if ((lo+8)//8)%8==0:print('fit factorial backgrounds',(lo+8)//8,'/',C.FIT,flush=True)
        finally:
            for h in handles:h.remove()
    arrays={};summary={}
    for (b,kind),v in totals.items():
        e,d,s=v/C.FIT;pure=residualize(e,d,s);key=array_key(b,kind)
        arrays[key]=pure;arrays[key+'_raw']=e.astype(np.float32);arrays[key+'_draft']=d.astype(np.float32);arrays[key+'_key_same']=s.astype(np.float32)
        summary[key]={'raw_E_norm':float(np.linalg.norm(e)),'adjusted_E_norm':float(np.linalg.norm(pure)),'draft_norm':float(np.linalg.norm(d)),
                      'key_same_norm':float(np.linalg.norm(s))}
    path=C.OUT/'directions.npz';np.savez_compressed(path,**arrays)
    result={**execution,'status':'complete','directions_sha256':C.file_sha(path),'one_token_pairs':len(fit)//8*12,
            'backgrounds':C.FIT,'factorial_effects':statistics(rows),'writer_norms':summary,'rows':rows}
    C.write_gz(dest,result);print('factorial effects',result['factorial_effects'],flush=True)


if __name__=='__main__':main()

"""Apply fixed learned evidence vectors to native Head/MLP writers at source tokens."""
from collections import defaultdict
from contextlib import contextmanager

import numpy as np
import torch

import mlp_factor_steer_common as C
from mlp_factor_steer_fit import array_key
from mlp_factor_steer_materials import WRITE_ROLES


def positions(rows,device):
    return torch.tensor([[r['anchors'][k] for k in WRITE_ROLES] for r in rows],device=device)


def orientation(rows,device):
    return torch.tensor([1. if r['expected']=='mining' else -1. for r in rows],device=device)


def load_vectors(device):
    path=C.OUT/'directions.npz';assert C.file_sha(path)==C.read_gz(C.OUT/'factorial-result.json.gz')['directions_sha256']
    with np.load(path) as arrays:return {k:torch.from_numpy(arrays[k]).to(device) for k in arrays if k.endswith(('_H','_M'))}


@contextmanager
def write(model,pos,sign,recipe,vectors,alpha,mode='joint',reference=None):
    """Modify exact head slices or MLP outputs. Match the real joint L2 before BF16 addition."""
    heads=defaultdict(list)
    if mode!='mlp_only':
        for b,h in recipe['heads']:heads[b].append(h)
    mlps=recipe['mlps'] if mode!='head_only' else []
    use_matched=mode=='matched';i,role=(pos>=0).nonzero().T;j=pos[i,role];hooks=[];norms={}
    def apply(value,key,delta):
        if use_matched:
            rng=np.random.default_rng(C.SEED+key[0]*53+key[1]);d=delta.shape[-1]
            permutation=torch.as_tensor(rng.permutation(d),device=value.device)
            signs=torch.as_tensor(rng.choice(np.asarray([-1,1],np.float32),size=d),device=value.device)
            delta=delta[:,permutation]*signs
            target=reference[key]['applied']
            length=delta.norm(dim=-1)
            delta=delta*(target/length.clamp_min(1e-30))[:,None]
            empty=length==0
            if empty.any():delta[empty,0]=target[empty]
        result=(value.float()+delta).to(value.dtype)
        norms[key]={'applied':(result.float()-value.float()).norm(dim=-1),'pre_rounding':delta.norm(dim=-1)}
        return result
    try:
        for b,hlist in heads.items():
            def edit_head(_,args,b=b,hlist=hlist):
                x=args[0];out=x.clone();anchor=x[i,j].reshape(len(i),32,128).clone()
                for h in hlist:
                    delta=vectors[array_key(b,'H')][h,role]*sign[i,None]*alpha
                    anchor[:,h]=apply(anchor[:,h],(b,h),delta)
                out[i,j]=anchor.flatten(1)
                return (out,*args[1:])
            hooks.append(model.model.layers[b].self_attn.o_proj.register_forward_pre_hook(edit_head))
        for b in mlps:
            def edit_mlp(_,args,x,b=b):
                out=x.clone();delta=vectors[array_key(b,'M')][0,role]*sign[i,None]*alpha
                out[i,j]=apply(x[i,j],(b,32),delta);return out
            hooks.append(model.model.layers[b].mlp.register_forward_hook(edit_mlp))
        yield norms
    finally:
        for h in hooks:h.remove()


def prefill(model,x,pos,sign,recipe,vectors,alpha,mode='joint',reference=None):
    with write(model,pos,sign,recipe,vectors,alpha,mode,reference) as norms:
        cache=model(input_ids=x[:,:C.CUT],use_cache=True,logits_to_keep=1).past_key_values
    return cache,norms

"""Replay the frozen directional writer on each independent task and monitor capabilities."""
import argparse
import time

import numpy as np
import torch
from scipy.stats import binomtest

import mlp_factor_steer_common as C
from mlp_factor_steer_materials import WRITE_ROLES
from mlp_factor_steer_fit import inputs
from mlp_factor_steer_edit import load_vectors, orientation, positions, prefill, write
from mlp_kv_behavior import word_indices
from mlp_kv_mediation import equal_rows, metrics
from mlp_read_route_causal import branch, changed, selected_slots
from mlp_fidelity_v2_tail import capability_interval, cluster_interval
from mlp_functional_trace import bit_array, load_model
from shared.dist_protocol.mechanism_trace import GpuLease


def norm_error(joint,matched,n):
    pre=[];post=[]
    for key,v in joint.items():
        target=v['applied'].clamp_min(1e-30);m=matched[key]
        pre.append(((m['pre_rounding']-v['applied']).abs()/target).reshape(n,4))
        post.append(((m['applied']-v['applied']).abs()/target).reshape(n,4))
    return torch.stack(pre,dim=1).flatten(1).cpu().numpy(),torch.stack(post,dim=1).flatten(1).cpu().numpy()


def raw_slots(cache,j,row):
    layer=cache.layers[35]
    return {role:{kind:bit_array(getattr(layer,kind)[j,:,row['anchors'][role]]).tolist() for kind in ['keys','values']}
            for role in WRITE_ROLES}


def evaluate_batch(model,tok,eos,rows,recipe,vectors,words):
    x=torch.tensor([r['tokens'] for r in rows],device='cuda');pos=positions(rows,x.device);s=orientation(rows,x.device)
    clean=model(input_ids=x[:,:C.CUT],use_cache=True,logits_to_keep=1).past_key_values
    edited,joint_norm=prefill(model,x,pos,s,recipe,vectors,recipe['alpha'])
    delta,restore,mask=changed(clean,edited)
    slots=[{'positions':{role:r['anchors'][role] for role in WRITE_ROLES},'clean':raw_slots(clean,j,r),'edited':raw_slots(edited,j,r)} for j,r in enumerate(rows)]
    relevant=sorted({b for b,_ in mask});source=selected_slots(edited,pos.cpu().tolist(),relevant)
    conditions={'clean':branch(model,x,clean,eos),'targeted':branch(model,x,edited,eos),'replay':branch(model,x,clean,eos,delta),
                'rescue':branch(model,x,edited,eos,restore),'source_only':branch(model,x,clean,eos,source)}
    for name,scale,mode in [('half',.5,'joint'),('matched',1.,'matched'),('head_only',1.,'head_only'),('mlp_only',1.,'mlp_only')]:
        cache,norm=prefill(model,x,pos,s,recipe,vectors,recipe['alpha']*scale,mode,joint_norm if mode=='matched' else None)
        conditions[name]=branch(model,x,cache,eos);del cache
        if name=='matched':pre,post=norm_error(joint_norm,norm,len(rows))
    replay=equal_rows(conditions['targeted'][0],conditions['replay'][0]);rescue=equal_rows(conditions['clean'][0],conditions['rescue'][0]);out=metrics(rows,conditions,tok,words)
    for j,r in enumerate(out):
        r.update(replay_logits_bitwise_equal=replay[j],rescue_logits_bitwise_equal=rescue[j],
                 replay_generation_equal=conditions['targeted'][1][j]==conditions['replay'][1][j],
                 rescue_generation_equal=conditions['clean'][1][j]==conditions['rescue'][1][j],
                 changed_slots={f'{b}:{k}':v[j].nonzero().flatten().cpu().tolist() for (b,k),v in mask.items()},
                 norm={'max_pre':float(pre[j].max()),'median_post':float(np.median(post[j])),'max_post':float(post[j].max()),'count':len(pre[j])})
    return out,slots


def summary(rows,eligible):
    n=len(rows)
    if not n:return {'n':0,'eligible':False,'passed':False,'operations':{}}
    baseline=np.asarray([r['conditions']['clean']['word']==r['contrast'] for r in rows]);ops={}
    for k in rows[0]['conditions']:
        values=[r['conditions'][k] for r in rows];alt=np.asarray([v['word']==r['contrast'] for v,r in zip(values,rows)])
        gain=int((alt&~baseline).sum());loss=int((~alt&baseline).sum())
        ops[k]={'accuracy':float(np.mean([v['correct'] for v in values])),'targeted_alt':int(alt.sum()),
                'targeted_gain':float(alt.mean()-baseline.mean()),'targeted_mcnemar_p':float(binomtest(gain,gain+loss).pvalue) if gain+loss else 1.,
                'mean_KL':float(np.mean([v['KL'] for v in values])),
                'target_gap_gain':cluster_interval([r['conditions']['clean']['gap']-v['gap'] for r,v in zip(rows,values)],C.SEED)}
    adv=ops['targeted']['targeted_gain']-ops['matched']['targeted_gain']
    return {'n':n,'eligible':eligible,'passed':bool(eligible and ops['targeted']['targeted_gain']>=.10 and ops['targeted']['targeted_mcnemar_p']<.025 and adv>=.05),
            'specificity':adv,'median_clean_gap':float(np.median([r['conditions']['clean']['gap'] for r in rows])),'operations':ops}


def holdout(model,tok,eos,task,recipe,vectors):
    corpus,prereg=inputs();pool=[r for r in corpus['heldout'] if r['task']==task];screen=C.read_gz(C.OUT/'screen.json.gz')
    assert screen['recipe_sha256']==C.file_sha(C.OUT/'frozen-recipe.json')
    idx=screen['enrolled'][task];words=word_indices(tok);rows=[];raw=[]
    for lo in range(0,len(idx),4):
        real=idx[lo:lo+4];pad=[i for i in range(4) if i not in real][:4-len(real)]
        batch=[pool[i] for i in real+pad];report,slots=evaluate_batch(model,tok,eos,batch,recipe,vectors,words)
        rows.extend(report[:len(real)]);raw.extend(slots[:len(real)])
        if (lo+len(real))%16==0:print(task,'mediation',lo+len(real),'/',len(idx),flush=True)
    diagnostics=[]
    def match(i,r):
        a=screen['rows'][task][i]['clean'];b=r['conditions']['clean'];return (a['word'],a['gap'])==(b['word'],b['gap'])
    for j,(i,r) in enumerate(zip(idx,rows)):
        if match(i,r):continue
        start=i//4*4;batch=pool[start:start+4];report,slots=evaluate_batch(model,tok,eos,batch,recipe,vectors,words)
        diagnostics.append({'index':j,'screen_index':i,'initial':r,'corrected':report[i-start],'batch_ids':[r['id'] for r in batch]})
        rows[j],raw[j]=report[i-start],slots[i-start]
    for j,r in enumerate(rows):r.update(index=j,screen_index=idx[j]);raw[j].update(id=r['id'],index=j)
    checks={k:sum(r[k] for r in rows) for k in ['replay_logits_bitwise_equal','rescue_logits_bitwise_equal','replay_generation_equal','rescue_generation_equal']}
    n=len(rows);clean_exact=sum(match(i,r) for i,r in zip(idx,rows));before=max((r['norm']['max_pre'] for r in rows),default=0.)
    checks.update(clean_exact=clean_exact,layout_corrections=len(diagnostics),max_pre_rounding_norm_error=before,
        max_post_rounding_norm_error=max((r['norm']['max_post'] for r in rows),default=0.),
        norm_vectors=sum(r['norm']['count'] for r in rows),
        no_cache_changes_before_origin=all(all(p>=min(raw[j]['positions'].values()) for ps in r['changed_slots'].values() for p in ps) for j,r in enumerate(rows)))
    ok=bool(screen['summary'][task]['power']['pass'] and clean_exact==n and before<1e-5 and
            checks['replay_logits_bitwise_equal']==n and checks['rescue_logits_bitwise_equal']==n)
    path=C.OUT/f'{task}-native.json.gz';C.write_gz(path,{'rows':raw,'dtype':'BF16 uint16','layer':35})
    return {'rows':rows,'summary':summary(rows,ok),'checks':checks,'layout_diagnostics':diagnostics,'native_sha256':C.file_sha(path)}


def capability(model,tok,frozen,vectors):
    data=C.read(C.CAP);assert sum(r['gate_eligible'] for r in data)==2200
    rcp=frozen['recipe'];letters=[tok.encode(c,add_special_tokens=False)[0] for c in 'ABCDE'];rows=[];norm_error=0.
    for lo in range(0,len(data),12):
        batch=data[lo:lo+12];prompts=[]
        for r in batch:
            text=r['question']+'\n'+'\n'.join(f'{a}. {v}' for a,v in zip('ABCDE',r['choices']))+'\n请只回答正确选项字母。'
            prompts.append(tok.encode(tok.apply_chat_template([{'role':'user','content':text}],tokenize=False,add_generation_prompt=True,enable_thinking=False),add_special_tokens=False))
        inputs={k:v.to('cuda') for k,v in tok.pad({'input_ids':prompts},padding=True,return_tensors='pt').items()};width=inputs['input_ids'].shape[1]
        p=torch.tensor([[width-1-frozen['offsets'][role] if frozen['offsets'][role]<len(q) else -1 for role in WRITE_ROLES] for q in prompts],device='cuda')
        assert len(set(frozen['offsets'].values()))==4
        sign=torch.tensor([1. if int(C.digest([C.SEED,'monitor',lo+j])[:8],16)%2 else -1. for j in range(len(batch))],device='cuda')
        clean=model(**inputs,use_cache=False,logits_to_keep=1).logits[:,-1]
        with write(model,p,sign,rcp,vectors,rcp['alpha']) as joint:edited=model(**inputs,use_cache=False,logits_to_keep=1).logits[:,-1]
        with write(model,p,sign,rcp,vectors,rcp['alpha'],'matched',joint) as control:matched=model(**inputs,use_cache=False,logits_to_keep=1).logits[:,-1]
        for key,z in joint.items():
            if len(z['applied']):norm_error=max(norm_error,float(((control[key]['pre_rounding']-z['applied']).abs()/z['applied'].clamp_min(1e-30)).max()))
        for j,r in enumerate(batch):
            predictions={}
            for k,logits in [('clean',clean),('targeted',edited),('matched',matched)]:
                pred='ABCDE'[int(logits[j,letters[:len(r['choices'])]].argmax())];predictions[k]={'predicted':pred,'correct':pred==r['answer']}
            rows.append({'index':lo+j,'id':r.get('id'),'source':r.get('source'),'expected':r['answer'],'gate_eligible':r['gate_eligible'],
                         'actual_offsets':[width-1-v for v in p[j].tolist() if v>=0],'conditions':predictions})
        if (lo+len(batch))%240==0:print('capability',lo+len(batch),'/',len(data),flush=True)
    mask=np.asarray([r['gate_eligible'] for r in rows]);baseline=[r['conditions']['clean']['correct'] for r in rows]
    return {'rows':rows,'summary':{k:capability_interval(baseline,[r['conditions'][k]['correct'] for r in rows],mask) for k in ['targeted','matched']},
            'reference_only':int((~mask).sum()),'max_pre_rounding_norm_error':norm_error,'input_sha256':C.file_sha(C.CAP)}


def main(part):
    out=C.OUT/f'{part}-result.json.gz'
    if out.exists():return
    frozen=C.read(C.OUT/'frozen-recipe.json');torch.set_num_threads(4);t=time.time()
    plan={**C.identity(),'schema':'factor_steer_holdout_execution.v1','part':part,'source_sha256':C.file_sha(__file__),
          'recipe_sha256':C.file_sha(C.OUT/'frozen-recipe.json'),'screen_sha256':C.file_sha(C.OUT/'screen.json.gz')}
    C.save(C.OUT/f'{part}-execution.json',plan)
    with GpuLease(),torch.inference_mode():
        model,tok,eos=load_model();vectors=load_vectors('cuda')
        result=capability(model,tok,frozen,vectors) if part=='capability' else holdout(model,tok,eos,part,frozen['recipe'],vectors)
    C.write_gz(out,{**plan,'status':'complete','seconds':time.time()-t,**result})
    print(part,'n',len(result['rows']),'checks',result.get('checks'),'seconds',round(time.time()-t,1),'summary',result['summary'],flush=True)


if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('part',choices=['lookup','dispatch','capability']);main(p.parse_args().part)

"""Native early-token writer intervention, precise cache replay and heldout read checks."""
import argparse
from contextlib import contextmanager
import time

import numpy as np
import torch
from scipy.stats import binomtest

import mlp_read_route_common as C
from mlp_read_route_probe import LAYERS, answer_read, batch_ids, cache_patch, gram, inputs, positions, read_statistics, token_indices
from mlp_kv_behavior import word_indices
from mlp_kv_mediation import equal_rows, metrics
from mlp_fidelity_v2_collect_v4 import greedy
from mlp_fidelity_v2_tail import capability_interval, cluster_interval
from mlp_functional_trace import bit_array, load_model
from shared.dist_protocol.mechanism_trace import GpuLease


@contextmanager
def writers(model,pos,heads,mlps,alpha,matched=False):
    device=model.model.layers[34].mlp.down_proj.weight.device;i,j=token_indices(pos,device)
    handles=[];norms={}
    def modify(source,key):
        delta=source.float()*alpha
        norm=delta.norm(dim=-1)
        if matched:
            rng=np.random.default_rng(C.SEED+key[0]*37+key[1]);n=delta.shape[-1]
            ix=torch.as_tensor(rng.permutation(n),device=device)
            sign=torch.as_tensor(rng.choice(np.asarray([-1,1],np.float32),size=n),device=device)
            delta=delta[:,ix]*sign
        value=(source.float()-delta).to(source.dtype)
        norms[f'{key[0]}:{key[1]}']={'batch_index':i.cpu().tolist(),'source_position':j.cpu().tolist(),
                                      'intended_L2':norm.cpu().tolist(),'applied_L2':(value.float()-source.float()).norm(dim=-1).cpu().tolist(),
                                      'pre_rounding_L2':delta.norm(dim=-1).cpu().tolist()}
        return value
    try:
        for b,h in heads:
            sl=slice(h*128,(h+1)*128)
            def replace(_,args,b=b,h=h,sl=sl):
                x=args[0];out=x.clone();out[i,j,sl]=modify(x[i,j,sl],(b,h));return (out,*args[1:])
            handles.append(model.model.layers[b].self_attn.o_proj.register_forward_pre_hook(replace))
        for b in mlps:
            def replace(_,args,value,b=b):
                out=value.clone();out[i,j]=modify(value[i,j],(b,32));return out
            handles.append(model.model.layers[b].mlp.register_forward_hook(replace))
        yield norms
    finally:
        for h in handles:h.remove()


def prefix(model,x,pos,heads=(),mlps=(),alpha=1.,matched=False):
    with writers(model,pos,heads,mlps,alpha,matched) as norms:
        cache=model(input_ids=x[:,:C.CUT],use_cache=True,logits_to_keep=1).past_key_values
    return cache,norms


def branch(model,x,cache,eos,patches=()):
    with cache_patch(cache,patches):
        out=model(input_ids=x[:,C.CUT:],past_key_values=cache,use_cache=True,logits_to_keep=1)
        logits=out.logits[:,-1].float();tokens=greedy(model,out.past_key_values,logits,eos,limit=4)
    return logits,tokens


def changed(clean,edited):
    forward=[];rescue=[];by_layer={}
    for b,(a,z) in enumerate(zip(clean.layers,edited.layers)):
        for kind in ['keys','values']:
            x=getattr(a,kind);y=getattr(z,kind)
            if torch.equal(x,y):continue
            diff=(x!=y).any(dim=-1).any(dim=1);begin=int(diff.nonzero()[:,1].min())
            ix=(slice(None),slice(None),slice(begin,C.CUT),slice(None))
            forward.append((b,kind,ix,y[ix].clone()));rescue.append((b,kind,ix,x[ix].clone()))
            by_layer[b,kind]=diff
    return forward,rescue,by_layer


def selected_slots(cache,pos,layers,kinds=('keys','values'),zero=False):
    first=cache.layers[0].keys;i,j=token_indices(pos,first.device);ix=(i,slice(None),j,slice(None));edits=[]
    for b in layers:
        for kind in kinds:
            value=getattr(cache.layers[b],kind)[ix]
            edits.append((b,kind,ix,torch.zeros_like(value) if zero else value.clone()))
    return edits


def direct_read(model,x,cache,pos,baseline):
    observed={}
    for b in LAYERS:
        patch=selected_slots(cache,pos,[b],kinds=('values',),zero=True)
        _,after=answer_read(model,x,cache,patch,[b]);a=baseline[b];z=after[b]
        prediction=[]
        for j,ps in enumerate(pos):
            index=torch.tensor(ps,device=x.device);w=a['weights'][j].index_select(-1,index)
            v=a['v'][j].index_select(-2,index);prediction.append(-torch.einsum('hp,hpd->hd',w,v))
        prediction=torch.stack(prediction).flatten(1);actual=(z['z'].float()-a['z'].float()).flatten(1)
        scale=prediction.norm(dim=-1)
        observed[b]={'Q_unchanged':equal_rows(a['q'].flatten(1),z['q'].flatten(1)),
                     'actual_delta_L2':actual.norm(dim=-1).cpu().tolist(),'predicted_delta_L2':scale.cpu().tolist(),
                     'relative_error':((actual-prediction).norm(dim=-1)/scale.clamp_min(1e-30)).cpu().tolist(),
                     'cosine':torch.nn.functional.cosine_similarity(actual,prediction,dim=-1).cpu().tolist()}
    return observed


def native_case(cache,j,ps):
    return {str(b):{kind:[bit_array(getattr(cache.layers[b],kind)[j,:,p]).tolist() for p in ps]
                    for kind in ['keys','values']} for b in LAYERS}


def execute_batch(model,tok,eos,rows,route,metric,words):
    x=batch_ids(rows);pos=positions(rows,route['roles']);heads,mlps=route['heads'],route['mlps']
    clean,_=prefix(model,x,pos);full,native_norm=prefix(model,x,pos,heads,mlps)
    delta,restore,changed_slots=changed(clean,full);layers=sorted({b for b,_ in changed_slots})
    raw=[{'positions':ps,'clean':native_case(clean,j,ps),'edited':native_case(full,j,ps)} for j,ps in enumerate(pos)]
    source_only=selected_slots(full,pos,layers);rest_only=delta+selected_slots(clean,pos,layers)
    cond={'clean':branch(model,x,clean,eos),'joint_1':branch(model,x,full,eos),
          'kv_replay':branch(model,x,clean,eos,delta),'kv_rescue':branch(model,x,full,eos,restore),
          'source_only':branch(model,x,clean,eos,source_only),'other_slots_only':branch(model,x,clean,eos,rest_only)}
    ctrl_norm=None
    for key,h,m,a,matched in [('joint_0.5',heads,mlps,.5,False),('head_only',heads,[],1.,False),
                               ('mlp_only',[],mlps,1.,False),('matched',heads,mlps,1.,True)]:
        edited,norm=prefix(model,x,pos,h,m,a,matched)
        cond[key]=branch(model,x,edited,eos)
        if matched:ctrl_norm=norm
        del edited
    clean_logits,fields=answer_read(model,x,clean);assert torch.equal(clean_logits,cond['clean'][0])
    observed=direct_read(model,x,clean,pos,fields);statistics=read_statistics(rows,fields,metric)
    weights=np.stack([fields[b]['weights'].cpu().numpy() for b in LAYERS],axis=1)
    reports=metrics(rows,cond,tok,words)
    replay=equal_rows(cond['joint_1'][0],cond['kv_replay'][0]);rescue=equal_rows(cond['clean'][0],cond['kv_rescue'][0])
    for j,r in enumerate(reports):
        def norms_for(norm):
            return {k:[{f:v[p] for f,v in data.items() if f!='batch_index'} for p,i in enumerate(data['batch_index']) if i==j] for k,data in norm.items()}
        r.update(replay_logits_bitwise_equal=replay[j],rescue_logits_bitwise_equal=rescue[j],
                 replay_generation_equal=cond['joint_1'][1][j]==cond['kv_replay'][1][j],rescue_generation_equal=cond['clean'][1][j]==cond['kv_rescue'][1][j],
                 changed_slots={f'{b}:{k}':v[j].nonzero().flatten().cpu().tolist() for (b,k),v in changed_slots.items()},
                 writer_norm={'joint':norms_for(native_norm),'matched':norms_for(ctrl_norm)},read=statistics[j],
                 read_verify={str(b):{k:v[j] for k,v in fields.items()} for b,fields in observed.items()})
    return reports,raw,weights


def summarize(rows,allowed,n_required):
    result={}
    groups={'all':rows,'confirm':[r for r in rows if r['split']=='confirm'],'lockbox':[r for r in rows if r['split']=='lockbox']}
    for key,group in groups.items():
        if not group:
            result[key]={'n':0,'eligible':False,'passed':False};continue
        base=np.asarray([r['conditions']['clean']['correct'] for r in group]);ops={}
        for op in group[0]['conditions']:
            compared=[r['conditions'][op] for r in group];correct=np.asarray([v['correct'] for v in compared])
            losses=int((base&~correct).sum());gains=int((~base&correct).sum())
            ops[op]={'accuracy':float(correct.mean()),'losses':losses,'gains':gains,'net_loss':float(base.mean()-correct.mean()),
                     'first_word_changes':sum(v['word']!=r['conditions']['clean']['word'] for v,r in zip(compared,group)),
                     'mcnemar_p':float(binomtest(losses,losses+gains).pvalue) if losses+gains else 1.,
                     'mean_KL':float(np.mean([v['KL'] for v in compared])),
                     'gap_delta':cluster_interval([v['gap']-r['conditions']['clean']['gap'] for v,r in zip(compared,group)],C.SEED)}
        h=ops['joint_1'];specific=h['net_loss']-ops['matched']['net_loss'];eligible=allowed and len(group)>=n_required
        result[key]={'n':len(group),'eligible':eligible,'passed':bool(eligible and h['net_loss']>=.1 and h['mcnemar_p']<.05 and specific>=.05),
                     'operations':ops,'specificity':specific,'median_clean_gap':float(np.median([r['conditions']['clean']['gap'] for r in group]))}
    return result


def causal(model,tok,eos,route):
    all_rows,prereg=inputs();screen=C.read_gz(C.OUT/'screen.json.gz')
    assert screen['route_sha256']==C.file_sha(C.OUT/'route-freeze.json')
    pool=[r for r in all_rows if r['split']!='discovery'];idx=screen['enrolled'];n=len(idx)
    if not n:return {'rows':[],'summary':{'all':{'n':0,'eligible':False,'passed':False}},'checks':{}}
    reports=[];raw=[];weights=[];word_ids=word_indices(tok);metric=gram(model)
    for lo in range(0,n,4):
        real=idx[lo:lo+4];pad=[i for i in range(4) if i not in real][:4-len(real)]
        batch=[pool[i] for i in real+pad];assert len(batch)==4
        info,slots,full=execute_batch(model,tok,eos,batch,route,metric,word_ids)
        reports.extend(info[:len(real)]);raw.extend(slots[:len(real)]);weights.extend(full[:len(real)])
        if (lo+len(real))%16==0:print('joint mediation',lo+len(real),'/',n,flush=True)
    def match(i,row):
        a=screen['rows'][i]['clean'];b=row['conditions']['clean']
        return (a['word'],a['gap'])==(b['word'],b['gap'])
    failures={j:i for j,i in enumerate(idx) if not match(i,reports[j])};layout=[]
    for j,i in failures.items():
        start=i//4*4;source=pool[start:start+4]
        info,slots,full=execute_batch(model,tok,eos,source,route,metric,word_ids);k=i-start
        layout.append({'screen_index':i,'initial':reports[j],'screen_batch_ids':[r['id'] for r in source],
                       'corrected':info[k],'screen':screen['rows'][i]['clean']})
        reports[j],raw[j],weights[j]=info[k],slots[k],full[k]
    matches=sum(match(i,r) for i,r in zip(idx,reports));assert len(reports)==n
    for j,r in enumerate(reports):r['index']=j;r['screen_index']=idx[j]
    arrays=C.OUT/'holdout-native.json.gz';C.write_gz(arrays,{'rows':[{'index':j,'id':reports[j]['id'],**v} for j,v in enumerate(raw)]})
    w=C.OUT/'holdout-weights.npz';np.savez_compressed(w,weights=np.asarray(weights,np.float32))
    checks={k:sum(r[k] for r in reports) for k in ['replay_logits_bitwise_equal','rescue_logits_bitwise_equal','replay_generation_equal','rescue_generation_equal']}
    checks.update(screen_exact=matches,layout_corrections=len(layout),only_B34_B35=all(all(k.startswith(('34:','35:')) for k in r['changed_slots']) for r in reports),
                  no_changes_before_earliest_origin=all(all(p>=min(raw[j]['positions']) for ps in r['changed_slots'].values() for p in ps) for j,r in enumerate(reports)),
                  nonzero_future_distribution_cases=sum(r['conditions']['joint_1']['KL']>0 for r in reports))
    read_summary={}
    for b in LAYERS:
        v=[r['read_verify'][str(b)] for r in reports]
        read_summary[str(b)]={'Q_unchanged':sum(z['Q_unchanged'] for z in v),'nonzero_read':sum(z['actual_delta_L2']>0 for z in v),
                              'median_cosine':float(np.median([z['cosine'] for z in v])),'median_relative_error':float(np.median([z['relative_error'] for z in v]))}
    return {'rows':reports,'summary':summarize(reports,matches==n,prereg['power_plan']['n_required']),
            'checks':checks,'layout_diagnostics':layout,'read_summary':read_summary,
            'native':{'raw_slots_sha256':C.file_sha(arrays),'full_weight_sha256':C.file_sha(w),'full_weight_shape':list(np.asarray(weights).shape)}}


def capability(model,tok,route):
    cases=C.read(C.CAP);assert sum(r['gate_eligible'] for r in cases)==2200
    letters=[tok.encode(c,add_special_tokens=False)[0] for c in 'ABCDE'];records=[]
    for lo in range(0,len(cases),12):
        batch=cases[lo:lo+12];prompts=[]
        for row in batch:
            text=row['question']+'\n'+'\n'.join(f'{a}. {v}' for a,v in zip('ABCDE',row['choices']))+'\n请只回答正确选项字母。'
            prompts.append(tok.encode(tok.apply_chat_template([{'role':'user','content':text}],tokenize=False,add_generation_prompt=True,
                          enable_thinking=False),add_special_tokens=False))
        data={k:v.to('cuda') for k,v in tok.pad({'input_ids':prompts},padding=True,return_tensors='pt').items()}
        size=data['input_ids'].shape[1];pos=[sorted({max(size-len(p),size-1-d) for d in route['capability_offsets']}) for p in prompts]
        scored={}
        for key,head,mlp,matched in [('clean',[],[],False),('joint',route['heads'],route['mlps'],False),('matched',route['heads'],route['mlps'],True)]:
            with writers(model,pos,head,mlp,1.,matched):logits=model(**data,use_cache=False,logits_to_keep=1).logits[:,-1]
            scored[key]=['ABCDE'[int(logits[j,letters[:len(r['choices'])]].argmax())] for j,r in enumerate(batch)]
        for j,r in enumerate(batch):
            records.append({'index':lo+j,'id':r.get('id'),'source':r.get('source'),'gate_eligible':r['gate_eligible'],'expected':r['answer'],
                            'actual_offsets':[size-1-v for v in pos[j]],'conditions':{k:{'predicted':v[j],'correct':v[j]==r['answer']} for k,v in scored.items()}})
        if (lo+len(batch))%240==0:print('capability',lo+len(batch),'/',len(cases),flush=True)
    mask=np.asarray([r['gate_eligible'] for r in records]);base=[r['conditions']['clean']['correct'] for r in records]
    return {'rows':records,'summary':{k:capability_interval(base,[r['conditions'][k]['correct'] for r in records],mask) for k in ['joint','matched']},
            'reference_only_n':int((~mask).sum()),'input_sha256':C.file_sha(C.CAP)}


def main(part):
    dest=C.OUT/f'{part}-result.json.gz'
    if dest.exists():return
    route=C.read(C.OUT/'route-freeze.json');torch.set_num_threads(4);start=time.time()
    freeze={**C.identity(),'schema':'mlp_early_token_intervention_execution.v1','part':part,'source_sha256':C.file_sha(__file__),
            'route_sha256':C.file_sha(C.OUT/'route-freeze.json'),'screen_sha256':C.file_sha(C.OUT/'screen.json.gz')}
    C.save(C.OUT/f'{part}-execution.json',freeze)
    with GpuLease(),torch.inference_mode():
        model,tok,eos=load_model()
        result=causal(model,tok,eos,route) if part=='causal' else capability(model,tok,route)
    C.write_gz(dest,{**freeze,'status':'complete','seconds':time.time()-start,**result})
    print(part,'n',len(result['rows']),'checks',result.get('checks'),'seconds',round(time.time()-start,1),flush=True)


if __name__=='__main__':
    parser=argparse.ArgumentParser();parser.add_argument('part',choices=['causal','capability']);main(parser.parse_args().part)

"""Intervene on native writes, then replay and rescue the exact autoregressive cache slots."""
import argparse
from collections import defaultdict
from contextlib import contextmanager
import time

import numpy as np
import torch
from scipy.stats import binomtest

import mlp_kv_common as C
from mlp_kv_behavior import frozen, score, word_indices
from mlp_kv_materials import CUT
from mlp_fidelity_v2_collect_v4 import greedy
from mlp_fidelity_v2_tail import capability_interval, cluster_interval
from mlp_functional_causal import edited
from mlp_functional_trace import bit_array, load_model
from shared.dist_protocol.mechanism_trace import GpuLease


def prefix(model,x,heads=(),mlps=(),alpha=1.):
    rows=torch.arange(len(x),device=x.device);positions=torch.full_like(rows,CUT-1);fields={}
    def capture(_,args):fields['incoming_b35']=args[0][:,-1].detach().clone()
    def head(_,args):fields['head34_2']=args[0][:,-1,2*128:3*128].detach().clone()
    # This observer sits before the edit; the actual KV is read after the full prefix forward.
    hooks=[model.model.layers[35].input_layernorm.register_forward_pre_hook(capture),
           model.model.layers[34].self_attn.o_proj.register_forward_pre_hook(head)]
    try:
        with edited(model,rows,positions,heads,mlps,alpha,True) as local:
            output=model(input_ids=x[:,:CUT],use_cache=True,logits_to_keep=1)
    finally:
        for hook in hooks:hook.remove()
    fields['pre_mlp_b35']=local[0]
    return output.past_key_values,fields


def slot(cache,b,k):
    layer=cache.layers[b]
    return (layer.keys if k=='K' else layer.values)[:,:,CUT-1,:]


def cache_changes(clean,edit,allowed):
    changed=[];other_positions=True
    for b,(a,z) in enumerate(zip(clean.layers,edit.layers)):
        for kind,v,w in [('K',a.keys,z.keys),('V',a.values,z.values)]:
            if torch.equal(v,w):continue
            changed.append((b,kind))
            other_positions &= torch.equal(v[:,:,:CUT-1],w[:,:,:CUT-1])
    return {'slots':changed,'only_allowed_layers':all(b in allowed for b,_ in changed),
            'all_earlier_positions_bitwise_equal':other_positions}


@contextmanager
def patched(cache,overrides):
    assert cache.get_seq_length()==CUT
    backup={key:slot(cache,*key).clone() for key in overrides}
    try:
        for key,value in overrides.items():slot(cache,*key).copy_(value)
        yield
    finally:
        cache.crop(CUT)
        for key,value in backup.items():slot(cache,*key).copy_(value)


def branch(model,x,cache,eos,overrides=None,generate=True):
    with patched(cache,overrides or {}):
        out=model(input_ids=x[:,CUT:],past_key_values=cache,use_cache=True,logits_to_keep=1)
        logits=out.logits[:,-1].detach().float()
        tokens=greedy(model,out.past_key_values,logits,eos,limit=4) if generate else None
    return logits,tokens


def take(cache,layers):return {(b,k):slot(cache,b,k).clone() for b in layers for k in ['K','V']}


def control(clean,changed):
    out={}
    for (b,k),value in changed.items():
        base=clean[b,k];delta=value.float()-base.float();rng=np.random.default_rng(C.SEED+b*17+(k=='V'))
        perm=torch.as_tensor(rng.permutation(delta.shape[-1]),device=base.device)
        signs=torch.as_tensor(rng.choice(np.asarray([-1,1],np.float32),size=delta.shape[-1]),device=base.device)
        out[b,k]=(base.float()+delta[...,perm]*signs).to(base.dtype)
    return out


def equal_rows(a,b):return (a==b).all(-1).cpu().tolist()


def metrics(rows,conditions,tok,word_ids):
    clean=conditions['clean'][0].double().log_softmax(-1);answer=[]
    for j,r in enumerate(rows):answer.append({k:v for k,v in r.items() if k!='tokens'}|{'conditions':{}})
    for name,(logits,generated) in conditions.items():
        q=logits.double().log_softmax(-1);kl=(clean.exp()*(clean-q)).sum(-1).cpu().tolist()
        for j,r in enumerate(rows):answer[j]['conditions'][name]=score(r,logits[j],generated[j],tok,word_ids)|{'KL':float(max(0.,kl[j]))}
    return answer


def summarize(rows,gate,minimum):
    groups={'all':rows,'confirm':[r for r in rows if r['split']=='confirm'],'lockbox':[r for r in rows if r['split']=='lockbox'],
            'low_margin':[r for r in rows if r['conditions']['clean']['correct'] and 0<r['conditions']['clean']['gap']<=8]}
    report={}
    for name,group in groups.items():
        if not group:
            report[name]={'n':0,'eligible':False};continue
        base=np.asarray([r['conditions']['clean']['correct'] for r in group],bool)
        ops={}
        for op in group[0]['conditions']:
            v=[r['conditions'][op] for r in group];actual=np.asarray([x['correct'] for x in v],bool)
            losses=int((base&~actual).sum());gains=int((~base&actual).sum())
            ops[op]={'accuracy':float(actual.mean()),'losses':losses,'gains':gains,
                     'net_loss':float(base.mean()-actual.mean()),'mcnemar_exact_p':float(binomtest(losses,losses+gains).pvalue) if losses+gains else 1.,
                     'mean_KL':float(np.mean([x['KL'] for x in v])),
                     'mean_gap':float(np.mean([x['gap'] for x in v])),
                     'gap_delta':cluster_interval([x['gap']-r['conditions']['clean']['gap'] for r,x in zip(group,v)],C.SEED)}
        spec=ops['head_full']['net_loss']-ops['matched']['net_loss'];h=ops['head_full']
        eligible=gate and len(group)>=minimum
        report[name]={'n':len(group),'eligible':eligible,'operations':ops,'loss_specificity':spec,
                      'passed':bool(eligible and h['net_loss']>=.10 and h['mcnemar_exact_p']<.05 and spec>=.05),
                      'interaction_gap':cluster_interval([r['conditions']['kv_replay']['gap']-r['conditions']['k_only']['gap']-r['conditions']['v_only']['gap']+r['conditions']['clean']['gap'] for r in group],C.SEED)}
    return report


def main(part):
    dest=C.OUT/f'{part}-result.json'
    if dest.exists():return
    corpus,prereg=frozen();formal=C.read(C.OUT/'formal-behavior.json');profile=formal['profile']
    chosen={b:int(C.digest([C.SEED,b,'causal'])[:8],16)%2 for b in range(32,288)}
    selected=[r for r in corpus if r['b'] in chosen and r['profile']==profile and r['t']==chosen[r['b']]];assert len(selected)==256
    plan={**C.identity(),'schema':'mlp_kv_mediation_execution.v1','part':part,'source_sha256':C.file_sha(__file__),
          'prereg_sha256':C.file_sha(C.OUT/'prereg.json'),'formal_sha256':C.file_sha(C.OUT/'formal-behavior.json'),
          'behavior_gate':formal['passed'],'profile':profile,'estimand':'conditional on behavior gate for task claims; exact transport is a separate computational check'}
    C.save(C.OUT/f'{part}-execution-prereg.json',plan)
    torch.set_num_threads(4);start=time.time()
    with GpuLease(),torch.inference_mode():
        model,tok,eos=load_model()
        if part=='mediation':result=mediate(model,tok,eos,selected,formal,prereg)
        elif part=='earlier':
            controls=[r for r in corpus if r['split']=='pilot' and r['profile']==profile][:8]
            result=earlier(model,tok,eos,[r for r in selected if r['split']=='lockbox'][:32])
            result['negative_controls']=negative(model,tok,eos,controls)
        else:result=capability(model,tok)
    C.save(dest,{**plan,'status':'complete',**result,'seconds':time.time()-start})
    print(part,{'seconds':round(time.time()-start,1),'rows':len(result['rows']),'checks':result.get('checks')},flush=True)


def mediate(model,tok,eos,items,formal,prereg):
    rows=[];scopes=[];native=defaultdict(list);words=word_indices(tok)
    for lo in range(0,len(items),4):
        batch=items[lo:lo+4];x=torch.tensor([r['tokens'] for r in batch],device='cuda')
        clean,raw0=prefix(model,x)
        edit,raw1=prefix(model,x,heads=[(34,2)])
        half,_=prefix(model,x,heads=[(34,2)],alpha=.5)
        scope=cache_changes(clean,edit,{35});scopes.append(scope)
        original=take(clean,[35]);replacement=take(edit,[35]);scrambled=control(original,replacement)
        cond={'clean':branch(model,x,clean,eos),'head_full':branch(model,x,edit,eos),'head_half':branch(model,x,half,eos),
              'kv_replay':branch(model,x,clean,eos,replacement),'kv_rescue':branch(model,x,edit,eos,original),
              'k_only':branch(model,x,clean,eos,{(35,'K'):replacement[35,'K']}),
              'v_only':branch(model,x,clean,eos,{(35,'V'):replacement[35,'V']}),
              'matched':branch(model,x,clean,eos,scrambled)}
        replay=equal_rows(cond['head_full'][0],cond['kv_replay'][0]);rescue=equal_rows(cond['clean'][0],cond['kv_rescue'][0])
        records=metrics(batch,cond,tok,words)
        delta_norm={k:(replacement[35,k].float()-original[35,k].float()).norm(dim=-1).cpu().tolist() for k in ['K','V']}
        norm_ratio={k:((scrambled[35,k].float()-original[35,k].float()).flatten(1).norm(dim=-1)/
                        (replacement[35,k].float()-original[35,k].float()).flatten(1).norm(dim=-1).clamp_min(1e-30)).cpu().tolist() for k in ['K','V']}
        for j,row in enumerate(records):
            row.update(index=lo+j,replay_logits_bitwise_equal=replay[j],rescue_logits_bitwise_equal=rescue[j],
                       replay_generation_equal=cond['head_full'][1][j]==cond['kv_replay'][1][j],
                       rescue_generation_equal=cond['clean'][1][j]==cond['kv_rescue'][1][j],
                       delta_KV_norm_by_GQA={k:v[j] for k,v in delta_norm.items()},scrambled_norm_ratio= {k:v[j] for k,v in norm_ratio.items()})
        rows.extend(records)
        for name,source in [('clean',original),('edited',replacement)]:
            for k in ['K','V']:native[f'{name}_{k}'].append(bit_array(source[35,k]))
        for name,values in [('clean',raw0),('edited',raw1)]:native[f'{name}_incoming_b35'].append(bit_array(values['incoming_b35']))
        native['clean_head34_2'].append(bit_array(raw0['head34_2']))
        if (lo+len(batch))%32==0:print('mediation',lo+len(batch),'/',len(items),flush=True)
    fields={k:np.concatenate(v) for k,v in native.items()};path=C.OUT/'native-slots.npz';np.savez(path,**fields)
    checks={k:sum(r[k] for r in rows) for k in ['replay_logits_bitwise_equal','rescue_logits_bitwise_equal','replay_generation_equal','rescue_generation_equal']}
    checks.update(only_B35_and_source=all(s['only_allowed_layers'] and s['all_earlier_positions_bitwise_equal'] for s in scopes),
                  nonzero_KV_cases=sum(any(x>0 for v in r['delta_KV_norm_by_GQA'].values() for x in v) for r in rows),
                  nonzero_future_distribution_cases=sum(r['conditions']['head_full']['KL']>0 for r in rows))
    return {'rows':rows,'checks':checks,'scopes':scopes,'summary':summarize(rows,formal['passed'],prereg['power_plan']['all_cases']['n_required']),
            'native':{'path':path.name,'sha256':C.file_sha(path),'dtype':'BF16 stored as uint16','fields':{k:list(v.shape) for k,v in fields.items()}}}


def earlier(model,tok,eos,items):
    rows=[];scopes=[];words=word_indices(tok)
    for lo in range(0,len(items),4):
        batch=items[lo:lo+4];x=torch.tensor([r['tokens'] for r in batch],device='cuda')
        clean,_=prefix(model,x);ablate,_=prefix(model,x,mlps=[33])
        scope=cache_changes(clean,ablate,{34,35});scopes.append(scope)
        a=take(clean,[34,35]);b=take(ablate,[34,35]);out={'clean':branch(model,x,clean,eos),'B33_MLP':branch(model,x,ablate,eos),
           'replay_both':branch(model,x,clean,eos,b),'rescue_both':branch(model,x,ablate,eos,a),
           'only_B34':branch(model,x,clean,eos,{k:v for k,v in b.items() if k[0]==34}),
           'only_B35':branch(model,x,clean,eos,{k:v for k,v in b.items() if k[0]==35})}
        for j,r in enumerate(metrics(batch,out,tok,words)):
            r.update(index=lo+j,replay_logits_bitwise_equal=bool(torch.equal(out['B33_MLP'][0][j],out['replay_both'][0][j])),
                     rescue_logits_bitwise_equal=bool(torch.equal(out['clean'][0][j],out['rescue_both'][0][j])))
            rows.append(r)
    checks={k:sum(r[k] for r in rows) for k in ['replay_logits_bitwise_equal','rescue_logits_bitwise_equal']}
    checks['only_B34_B35_and_source']=all(s['only_allowed_layers'] and s['all_earlier_positions_bitwise_equal'] for s in scopes)
    ops={name:{'mean_KL':float(np.mean([r['conditions'][name]['KL'] for r in rows])),
               'accuracy':float(np.mean([r['conditions'][name]['correct'] for r in rows]))} for name in rows[0]['conditions']}
    return {'rows':rows,'checks':checks,'scopes':scopes,'summary':{'operations':ops,'n':len(rows),'evidence':'engineering and descriptive endpoint; n32'}}


def negative(model,tok,eos,items):
    checks=[]
    for lo in range(0,len(items),4):
        batch=items[lo:lo+4];x=torch.tensor([r['tokens'] for r in batch],device='cuda')
        clean,raw0=prefix(model,x);neg,rawneg=prefix(model,x,heads=[(35,25)])
        cache_equal=not cache_changes(clean,neg,set())['slots']
        baseline=branch(model,x,clean,eos);edited_out=branch(model,x,neg,eos)
        for j,r in enumerate(batch):
            checks.append({'id':r['id'],'cache_bitwise_equal':cache_equal,
                'logits_bitwise_equal':bool(torch.equal(baseline[0][j],edited_out[0][j])),
                'generation_equal':baseline[1][j]==edited_out[1][j],
                'local_residual_delta_L2':float((rawneg['pre_mlp_b35'][j]-raw0['pre_mlp_b35'][j]).norm())})
    return checks


def capability(model,tok):
    inputs=C.read(C.CAP);assert sum(r['gate_eligible'] for r in inputs)==2200
    letters=[tok.encode(c,add_special_tokens=False)[0] for c in 'ABCDE'];rows=[]
    offset=42  # 1034-token prompt, source index 991.
    for lo in range(0,len(inputs),12):
        batch=inputs[lo:lo+12];prompts=[]
        for r in batch:
            text=r['question']+'\n'+'\n'.join(f'{a}. {v}' for a,v in zip('ABCDE',r['choices']))+'\n请只回答正确选项字母。'
            prompts.append(tok.encode(tok.apply_chat_template([{'role':'user','content':text}],tokenize=False,
                    add_generation_prompt=True,enable_thinking=False),add_special_tokens=False))
        data={k:v.to('cuda') for k,v in tok.pad({'input_ids':prompts},padding=True,return_tensors='pt').items()}
        size=data['input_ids'].shape[1];position=torch.tensor([max(size-len(p),size-1-offset) for p in prompts],device='cuda');idx=torch.arange(len(batch),device='cuda')
        predictions={}
        for name,heads,mlps in [('clean',[],[]),('B34_H2',[(34,2)],[]),('B33_MLP',[],[33])]:
            with edited(model,idx,position,heads,mlps,1.,False):logits=model(**data,use_cache=False,logits_to_keep=1).logits[:,-1]
            predictions[name]=['ABCDE'[int(logits[j,letters[:len(r['choices'])]].argmax())] for j,r in enumerate(batch)]
        for j,r in enumerate(batch):
            rows.append({'index':lo+j,'id':r.get('id'),'source':r.get('source'),'gate_eligible':r['gate_eligible'],'expected':r['answer'],
                         'actual_offset':int(size-1-position[j]),'conditions':{name:{'predicted':v[j],'correct':v[j]==r['answer']} for name,v in predictions.items()}})
        if (lo+len(batch))%240==0:print('capability',lo+len(batch),'/',len(inputs),flush=True)
    mask=np.asarray([r['gate_eligible'] for r in rows],bool);clean=[r['conditions']['clean']['correct'] for r in rows]
    return {'rows':rows,'summary':{name:capability_interval(clean,[r['conditions'][name]['correct'] for r in rows],mask) for name in ['B34_H2','B33_MLP']},
            'reference_only_n':int((~mask).sum()),'offset':offset,'input_sha256':C.file_sha(C.CAP)}


